import { Pool } from "pg";
import AxeBuilder from "@axe-core/playwright";
import { test, expect, setThemeQuotaGating } from "../helpers/theme-browser";

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
test.beforeEach(async () => {
  await setThemeQuotaGating(true);
});
test.afterAll(async () => {
  await pool.end();
});

test("daily banner stays compact across themes and appears only on Compose and Usage", async ({
  page,
  themeUser,
}, testInfo) => {
  await pool.query(`UPDATE "User" SET "gmailAuthorized"=true WHERE id=$1`, [
    themeUser,
  ]);
  const resetAt = new Date(Date.now() + 3 * 60 * 60_000).toISOString();
  const hydrationErrors: string[] = [];
  page.on("pageerror", (error) => {
    if (/hydration|hydrating/i.test(error.message))
      hydrationErrors.push(error.message);
  });
  await page.route("**/api/quota", async (route) => {
    const response = await route.fetch();
    const quota = await response.json();
    quota.mode = "gated";
    quota.sendingAllowed = true;
    quota.daily = {
      sent: 2,
      reserved: 1,
      used: 3,
      limit: 3,
      remaining: 0,
      startsAt: "2026-10-30T00:00:00Z",
      endsAt: resetAt,
      resetsAt: resetAt,
    };
    quota.monthly = { ...quota.daily, used: 3, limit: 300, remaining: 297 };
    await route.fulfill({ response, json: quota });
  });
  async function refresh(expectedCount = 1) {
    await expect(async () => {
      await Promise.all([
        page.waitForResponse(
          (r) => new URL(r.url()).pathname === "/api/quota",
          { timeout: 1000 },
        ),
        page.evaluate(() =>
          window.dispatchEvent(new Event("focus")),
        ),
      ]);
    }).toPass({ timeout: 15000 });
    await expect(
      page.getByRole("status", { name: "Daily limit reached" }),
    ).toHaveCount(expectedCount);
  }
  await page.goto("/usage");
  await refresh();
  const banner = page.getByRole("status", { name: "Daily limit reached" });
  for (const theme of [
    "Lavender Light",
    "Nightbloom Dark",
    "Chalk Light",
    "Obsidian Dark",
  ]) {
    await page.getByRole("button", { name: "Choose appearance" }).click();
    await page.getByRole("menuitemradio", { name: theme, exact: true }).click();
    for (const width of [1280, 820, 390]) {
      await page.setViewportSize({ width, height: 900 });
      const toggle = banner.getByRole("button", { name: "Details" });
      await expect(toggle).toHaveAttribute("aria-expanded", "false");
      await expect(banner.getByRole("img")).toHaveAttribute(
        "aria-label",
        "3 of 3 daily emails used",
      );
      await expect(banner).toHaveCSS("font-family", /.*Plus.*|.*plus.*/);
      await toggle.focus();
      await page.keyboard.press("Enter");
      await expect(toggle).toHaveAttribute("aria-expanded", "true");
      await expect(
        banner.getByRole("link", { name: "View allowances & reset times" }),
      ).toBeVisible();
      await expect(banner.getByText("(your time)")).toBeVisible();
      await banner.screenshot({
        animations: "disabled",
        path: testInfo.outputPath(
          `${theme.split(" ")[0]}-${width}-expanded.png`,
        ),
      });
      if (width === 1280)
        expect(
          (
            await new AxeBuilder({ page })
              .include('[aria-label="Daily limit reached"]')
              .analyze()
          ).violations,
        ).toEqual([]);
      await toggle.click();
      await expect(toggle).toHaveAttribute("aria-expanded", "false");
      await expect(banner.locator("[inert]")).toHaveCount(1);
      await expect(async () => {
        const height = await banner.evaluate(
          (el) => el.getBoundingClientRect().height,
        );
        expect(height).toBeLessThan(width < 760 ? 280 : 180);
      }).toPass();
      expect(
        await banner.evaluate((el) => el.scrollWidth > el.clientWidth),
      ).toBe(false);
      await banner.screenshot({
        animations: "disabled",
        path: testInfo.outputPath(
          `${theme.split(" ")[0]}-${width}-collapsed.png`,
        ),
      });
    }
  }
  for (const path of [
    "/compose",
    "/templates",
    "/contacts",
    "/usage",
    "/history",
    "/settings",
  ]) {
    await page.goto(path);
    await refresh(path === "/compose" || path === "/usage" ? 1 : 0);
  }
  const navigation = page.getByRole("navigation", { name: "Main navigation" });
  for (const name of [
    "Compose",
    "Templates",
    "Contacts",
    "Usage",
    "History",
    "Settings",
    "Compose",
  ]) {
    await navigation.getByRole("link", { name, exact: true }).click();
    await expect(page).toHaveURL(new RegExp(`/${name.toLowerCase()}$`));
    await refresh(name === "Compose" || name === "Usage" ? 1 : 0);
  }
  expect(hydrationErrors).toEqual([]);
});

test("Premium meter, countdown expiry, live quota updates and reduced motion", async ({
  page,
  themeUser,
}, testInfo) => {
  await pool.query(`UPDATE "User" SET "gmailAuthorized"=true WHERE id=$1`, [
    themeUser,
  ]);
  let used = 22;
  let limit = 20;
  let requests = 0;
  const resetAt = new Date(Date.now() + 60000).toISOString();
  await page.route("**/api/quota", async (route) => {
    requests++;
    const response = await route.fetch();
    const quota = await response.json();
    quota.mode = "gated";
    quota.sendingAllowed = true;
    quota.daily = {
      used,
      limit,
      sent: used,
      reserved: 0,
      remaining: Math.max(0, limit - used),
      startsAt: "2026-01-01T00:00:00Z",
      endsAt: resetAt,
      resetsAt: resetAt,
    };
    quota.monthly = { ...quota.daily, used: 22, limit: 300, remaining: 278 };
    await route.fulfill({ response, json: quota });
  });
  await page.goto("/usage");
  await expect(async () => {
    await Promise.all([
      page.waitForResponse((r) => new URL(r.url()).pathname === "/api/quota", {
        timeout: 1000,
      }),
      page.evaluate(() =>
        window.dispatchEvent(new Event("mailloop:access-refresh")),
      ),
    ]);
  }).toPass({ timeout: 15000 });
  const banner = page.getByRole("status", { name: "Daily limit reached" });
  await expect(banner).toBeVisible();
  await expect(banner.getByRole("img").locator("span")).toHaveCount(20);
  for (const width of [1280, 820, 390]) {
    await page.setViewportSize({ width, height: 900 });
    await banner.screenshot({
      path: testInfo.outputPath(`premium-${width}.png`),
      animations: "disabled",
    });
    expect(await banner.evaluate((el) => el.scrollWidth > el.clientWidth)).toBe(
      false,
    );
  }
  await page.emulateMedia({ reducedMotion: "reduce" });
  await expect(banner.getByRole("img").locator("span").first()).toHaveCSS(
    "animation-name",
    "none",
  );
  await page.clock.install();
  await page.clock.fastForward(61000);
  await expect(banner.getByText("Ready", { exact: true })).toBeVisible();
  const afterReady = requests;
  await page.clock.fastForward(3000);
  expect(requests).toBe(afterReady);
  used = 2;
  limit = 3;
  await page.evaluate(() =>
    window.dispatchEvent(new Event("mailloop:access-refresh")),
  );
  await expect(banner).toHaveCount(0);
});
